6	const SPHINX = "sphinx";
7	
8	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
9	
10	const countMonsterTypes = (army: Card[]): number =>
11	  new Set(army.map((card) => card.monster)).size;
