13	// Points per Sphinx step up with the army's variety. Deliberately a step
14	// table, not a formula: the remaining examples decide the rule's true shape.
15	// Ordered from the most varied army down; the first tier the army reaches wins.
16	const POINTS_PER_SPHINX_TIERS: { minMonsterTypes: number; pointsPerSphinx: number }[] = [
17	  { minMonsterTypes: 6, pointsPerSphinx: 5 },
18	  { minMonsterTypes: 4, pointsPerSphinx: 3 },
19	];
20	
21	const BASE_POINTS_PER_SPHINX = 2;
22	
23	const scorePerSphinx = (monsterTypeCount: number): number =>
24	  POINTS_PER_SPHINX_TIERS.find((tier) => monsterTypeCount >= tier.minMonsterTypes)
25	    ?.pointsPerSphinx ?? BASE_POINTS_PER_SPHINX;
26	
27	export const scoreArmy = (army: Card[]): number =>
28	  army.filter(isSphinx).length * scorePerSphinx(countMonsterTypes(army));
